def _make_view(cls, *args, **kwargs):
    """Instantiate a discord.ui.View subclass (needs a running event loop)."""
    result = [None]

    async def _create():
        result[0] = cls(*args, **kwargs)

    asyncio.run(_create())
    return result[0]


