class TestSharedGames:
    """`Games Together` under .relations @player: only the games both played."""

    @pytest.fixture(autouse=True)
    def setup_db(self, tmp_path):
        db_path = os.path.join(tmp_path, "test_shared.db")
        self.db = seed_db(db_path)

    def test_lists_only_shared_games_newest_first(self):
        shared = self.db.get_shared_games(100, 101)
        assert [g["game_number"] for g in shared] == [4, 2, 1]

    def test_players_with_no_shared_games(self):
        # Grace only played game 3, Kate only game 5.
        assert self.db.get_shared_games(106, 110) == []

    def test_marks_same_team_as_allies(self):
        shared = self.db.get_shared_games(100, 102)  # Alice + Charlie are both Village
        assert len(shared) == 1
        assert shared[0]["same_team"] is True
        assert shared[0]["my_role"] == "Villager"
        assert shared[0]["their_role"] == "Seer"

    def test_marks_opposing_teams(self):
        shared = self.db.get_shared_games(100, 101)
        assert all(g["same_team"] is False for g in shared)

    def test_carries_both_roles_teams_and_results(self):
        shared = self.db.get_shared_games(100, 101)
        game_one = shared[-1]
        assert game_one["my_role_id"] == 1
        assert game_one["their_role_id"] == 2
        assert game_one["my_team"] == 1
        assert game_one["their_team"] == 2
        assert game_one["my_result"] == "❌ Loss"
        assert game_one["their_result"] == "🏆 Win"

    def test_shared_games_match_relation_counts(self):
        same_wins, same_games, diff_games, _my_wins, _their_wins = (
            self.db.get_relation_between(100, 101)
        )
        shared = self.db.get_shared_games(100, 101)
        assert same_games + diff_games == len(shared)

    def test_one_entry_per_game(self):
        shared = self.db.get_shared_games(100, 101)
        numbers = [g["game_number"] for g in shared]
        assert len(numbers) == len(set(numbers))


