class TestNemesisIdentityMerging:
    """One player recorded under several names must count as a single person.

    `player_name` is free text written per game, so a player who appears as a
    nickname in some games and a username in others used to be split into one
    nemesis row per name — listing the same person twice and splitting their
    real record across several weak entries.
    """

    # Rival (id 2) is recorded as "RivalName" then later as "RivalAlias".
    NEMESIS_SEED = [
        (1, "g1", 1, "Villager", 1, "Subject", 1, 0, 1),
        (1, "g1", 2, "Wolf",     2, "RivalName", 2, 1, 1),
        (2, "g2", 1, "Villager", 1, "Subject", 1, 0, 1),
        (2, "g2", 2, "Wolf",     2, "RivalAlias", 2, 1, 1),
        (3, "g3", 1, "Villager", 1, "Subject", 1, 1, 1),
        (3, "g3", 2, "Wolf",     2, "Harmless", 3, 0, 1),
        # Same team as Subject, under a second name, to guard the ally path too.
        (4, "g4", 1, "Villager", 1, "Subject", 1, 1, 1),
        (4, "g4", 2, "Doctor",   1, "PalName", 4, 1, 1),
        (5, "g5", 1, "Villager", 1, "Subject", 1, 1, 1),
        (5, "g5", 2, "Doctor",   1, "PalAlias", 4, 1, 1),
    ]
    NEMESIS_COLUMNS = "game_number, game_name, role_id, role_name, team, player_name, player_id, win, count"

    @pytest.fixture
    def db(self, tmp_path):
        db_path = os.path.join(tmp_path, "test_nemesis_identity.db")
        db = library_cog.LibraryDatabase(db_path)
        conn = sqlite3.connect(db_path)
        conn.executemany(
            f"INSERT INTO roles ({self.NEMESIS_COLUMNS}) VALUES ({','.join(['?'] * 9)})",
            self.NEMESIS_SEED,
        )
        conn.commit()
        conn.close()
        return db

    def test_opponent_rows_have_no_duplicate_player_ids(self, db):
        """The core regression: the same player_id must not appear twice."""
        rows = db._get_opponent_rows(1)
        ids = [r[0] for r in rows]
        assert len(ids) == len(set(ids)), "same player returned more than once"

    def test_opponent_names_differ_only_by_history(self, db):
        """A rename must not create a second opponent row."""
        rows = db._get_opponent_rows(1)
        names = [r[1] for r in rows]
        assert "RivalName" not in names, "stale name still treated as its own player"
        assert "RivalAlias" in names

    def test_losses_and_games_are_summed_across_names(self, db):
        """The merged record is the real total, not one fragment."""
        rows = {r[0]: r for r in db._get_opponent_rows(1)}
        _, _, losses, games = rows[2]
        assert (losses, games) == (2, 2)

    def test_display_name_is_the_most_recent_one(self, db):
        """Show the name the player is currently recorded under."""
        rows = {r[0]: r[1] for r in db._get_opponent_rows(1)}
        assert rows[2] == "RivalAlias"

    def test_display_name_falls_back_when_no_name_recorded(self, db):
        """A player with no usable name still renders instead of crashing."""
        rows = {r[0]: r[1] for r in db._get_opponent_rows(1)}
        assert rows[3] == "Harmless"

    def test_top_nemeses_lists_each_player_once(self, db):
        """`.stats` must not show the same nemesis under two names."""
        nemeses = db.get_top_nemeses2(1)
        ids = [n[0] for n in nemeses]
        assert len(ids) == len(set(ids)), "duplicate nemesis in top list"
        rival = [n for n in nemeses if n[0] == 2]
        assert len(rival) == 1
        assert (rival[0][2], rival[0][3]) == (2, 2), "loss count not merged"

    def test_all_nemeses_lists_each_player_once(self, db):
        """The `.relations` view uses the same rows and must be deduped too."""
        nemeses = db.get_all_nemeses2(1)
        ids = [n[0] for n in nemeses]
        assert len(ids) == len(set(ids))

    def test_nemesis_rate_is_computed_from_merged_totals(self, db):
        """Rate uses the merged totals, so 2 losses in 2 games reads 100%."""
        rival = [n for n in db.get_top_nemeses2(1) if n[0] == 2][0]
        assert rival[4] == 1.0

    def test_teammate_rows_stay_deduped(self, db):
        """Refactoring the name lookup must not regress the ally path."""
        rows = db._get_teammate_rows(1)
        ids = [r[0] for r in rows]
        assert len(ids) == len(set(ids))
        pal = {r[0]: r for r in rows}[4]
        assert (pal[2], pal[3]) == (2, 2), "ally wins/games not merged"
        assert pal[1] == "PalAlias"

    def test_top_allies_lists_each_player_once(self, db):
        allies = db.get_top_allies2(1)
        ids = [a[0] for a in allies]
        assert len(ids) == len(set(ids))


class TestLeaderboardMvpPercentage:
    """The .stats leaderboard must offer an MVP% sort (MVPs / games played)."""

    @staticmethod
    def _stats(name, games, mvps):
        return {
            "player_name": name,
            "games": games,
            "wins": 0,
            "winrate": 0.0,
            "total_mvps": mvps,
        }

    def test_sorted_by_mvp_percentage(self):
        stats = [
            self._stats("Low", 10, 1),     # 10%
            self._stats("High", 10, 5),    # 50%
            self._stats("Mid", 20, 8),     # 40%
        ]
        view = _make_view(library_cog.LeaderboardView, stats, 1, "mvp_pct")
        names = [p["player_name"] for p in view.get_sorted_players()]
        assert names == ["High", "Mid", "Low"]

    def test_mvp_pct_option_is_in_sort_select(self):
        view = _make_view(
            library_cog.LeaderboardView,
            [self._stats("Alice", 10, 5)],
            1,
            "mvp_pct",
        )
        select = next(c for c in view.children if isinstance(c, discord.ui.Select))
        assert any(o.value == "mvp_pct" for o in select.options)

    def test_embed_shows_rate_and_sort_label(self):
        view = _make_view(
            library_cog.LeaderboardView,
            [self._stats("Alice", 10, 5)],
            1,
            "mvp_pct",
        )
        embed = view.get_embed()
        assert "MVP Rate: 50.0% (5 MVPs / 10G)" in embed.description
        assert "Sorted by MVP %" in embed.footer.text
